do $do$
declare run_id bigint; cid bigint;
begin
select id into cid from public.companies where ticker=$q$CBRS$q$;
if cid is null then raise exception 'company % not found', $q$CBRS$q$; end if;
insert into public.agent_runs(agent_name,mode,target,model,tokens_in,tokens_out,cost_usd,started_at,finished_at,status,review_status) values ('market_data','batch',$q$CBRS Finnhub metric, recommendation trends, earnings calendar (M17)$q$,'none (Finnhub API, no model call)',0,0,0,$q$2026-10-24T06:43:18.436625+00:00$q$::timestamptz,$q$2026-10-24T06:43:22.775157+00:00$q$::timestamptz,$q$completed_with_gaps$q$,'unreviewed') returning id into run_id;
insert into public.company_metrics(company_id,as_of,data_period,pe_ttm,ev_ebitda,gross_margin,operating_margin,net_margin,revenue_growth_yoy,debt_to_equity,rec_period,rec_strong_buy,rec_buy,rec_hold,rec_sell,rec_strong_sell,source,fetched_at,status,run_id,note) values (cid,$q$2026-10-24$q$::date,$q$2026-06-30$q$::date,null,null,null,null,null,null,0.1003,$q$2026-10-01$q$::date,4,11,3,0,0,'finnhub',$q$2026-10-24T06:43:22.775157+00:00$q$::timestamptz,'staged',run_id,$q$missing from Finnhub: peTTM, evEbitdaTTM, grossMarginTTM, operatingMarginTTM, netProfitMarginTTM, revenueGrowthTTMYoy$q$) on conflict (company_id,as_of,source) do update set data_period=excluded.data_period,pe_ttm=excluded.pe_ttm,ev_ebitda=excluded.ev_ebitda,gross_margin=excluded.gross_margin,operating_margin=excluded.operating_margin,net_margin=excluded.net_margin,revenue_growth_yoy=excluded.revenue_growth_yoy,debt_to_equity=excluded.debt_to_equity,rec_period=excluded.rec_period,rec_strong_buy=excluded.rec_strong_buy,rec_buy=excluded.rec_buy,rec_hold=excluded.rec_hold,rec_sell=excluded.rec_sell,rec_strong_sell=excluded.rec_strong_sell,fetched_at=excluded.fetched_at,run_id=excluded.run_id,note=excluded.note where public.company_metrics.status='staged';
delete from public.company_events where company_id=cid and source='finnhub' and status='staged' and event_date>=$q$2026-10-24$q$::date and event_date not in ($q$2026-11-12$q$::date);
insert into public.company_events(company_id,event_date,event_type,detail,source,fetched_at,status,run_id) values (cid,$q$2026-11-12$q$::date,'earnings',$q$Q3 2026$q$,'finnhub',$q$2026-10-24T06:43:22.775157+00:00$q$::timestamptz,'staged',run_id) on conflict (company_id,event_date,event_type,source) where status='staged' do update set detail=excluded.detail,fetched_at=excluded.fetched_at,run_id=excluded.run_id;
end $do$;
